BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(27);
SELECT ok(to_regclass('app_private.admission_application_policy_snapshots') IS NOT NULL,'P44 snapshot relation exists');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_policy_snapshot_intake_source_key' AND conrelid='app_private.admission_document_intakes'::regclass AND contype='u' AND cardinality(conkey)=3),'intake exposes exact application policy composite key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_policy_snapshot_forward_source_key' AND conrelid='app_private.admission_document_forwards'::regclass AND contype='u' AND cardinality(conkey)=4),'forward exposes application intake version composite key');
SELECT ok((SELECT attnotnull FROM pg_attribute WHERE attrelid='app_private.admission_application_policy_snapshots'::regclass AND attname='forward_id'),'forward id is mandatory');
SELECT ok((SELECT attnotnull FROM pg_attribute WHERE attrelid='app_private.admission_application_policy_snapshots'::regclass AND attname='document_intake_id'),'document intake id is mandatory');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_forward' AND conrelid='app_private.admission_application_policy_snapshots'::regclass AND contype='f' AND cardinality(conkey)=4),'snapshot has four-field exact Forward FK');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_intake_policy' AND conrelid='app_private.admission_application_policy_snapshots'::regclass AND contype='f' AND cardinality(conkey)=3),'snapshot has three-field exact Intake policy FK');
SELECT ok((SELECT confrelid='app_private.admission_document_forwards'::regclass FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_forward'),'Forward FK targets retained document Forward');
SELECT ok((SELECT confrelid='app_private.admission_document_intakes'::regclass FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_intake_policy'),'Intake FK targets retained document Intake');
SELECT ok((SELECT confupdtype='r' AND confdeltype='r' FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_forward'),'Forward FK disallows update and delete');
SELECT ok((SELECT confupdtype='r' AND confdeltype='r' FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_intake_policy'),'Intake FK disallows update and delete');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%application_version%' AND pg_get_constraintdef(oid) LIKE '%document_intake_id%' FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_forward'),'Forward FK includes exact application version and intake');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%policy_version_id%' AND pg_get_constraintdef(oid) LIKE '%application_id%' FROM pg_constraint WHERE conname='db03_policy_snapshot_exact_intake_policy'),'Intake FK includes exact application and policy');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%policy_version_id%' FROM pg_constraint WHERE conname='db03_policy_snapshot_intake_source_key'),'retained intake unique key covers selected policy');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%application_version%' FROM pg_constraint WHERE conname='db03_policy_snapshot_forward_source_key'),'retained Forward unique key covers version');
SELECT ok(to_regprocedure('app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)') IS NOT NULL,'P46A private read-only policy candidate remains installed');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_policy_snapshot_same_application_version'),'P45 Student handoff policy linkage unchanged');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_policy_snapshot_mutation_disabled' AND NOT tgisinternal AND tgenabled='O'),'P44 deny-all mutation trigger remains enabled');
SELECT ok((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='app_private.admission_application_policy_snapshots'::regclass),'snapshot remains under forced row-level security');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_application_policy_snapshots','INSERT'),'clients cannot create snapshots');
SELECT ok(NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_application_policy_snapshots','INSERT'),'workflow executor cannot create snapshots');
SELECT ok(NOT has_table_privilege('schoolos_student_executor','app_private.admission_application_policy_snapshots','INSERT'),'D1 executor cannot create snapshots');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_unsubmitted_policy_null' AND conrelid='app_private.admission_applications'::regclass),'S5 draft application policy projection remains blocked');
SELECT ok(to_regprocedure('app.bind_admission_application_policy(uuid,bigint,uuid,text)') IS NULL,'no new client policy-binding API');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'Principal approval and Student creation remain disabled');
SELECT throws_ok($q$INSERT INTO app_private.admission_application_policy_snapshots DEFAULT VALUES$q$,'P0001','DB03 admission policy snapshot writer unavailable','P44 snapshot writer still rejects inserts');
SELECT ok((SELECT count(*)=0 FROM app_private.admission_application_policy_snapshots),'lineage migration does not create any snapshot');
SELECT * FROM finish();
ROLLBACK;
